#include <set>
#include <iostream>

int main() {
    std::set<float> c;  // A set of floats, implemented as a red-black tree
    float value = 3.14f;  // Value to insert

    // Define variable for return value of insert()
    std::pair<std::set<float>::iterator, bool> status;

    // Insert value and assign return value
    status = c.insert(value);

    // Process return value
    if (status.second) {
        std::cout << "Insertion successful: " << *status.first << std::endl;  // Dereference iterator to access value
    } else {
        std::cout << "Element already exists at: " << *status.first << std::endl;  // Iterator points to existing element
    }

    return 0;
}
